/* Synthetic vectors are generated by an independent host implementation. */
#include "seeded_rng.h"
#include <string.h>
#include "vectors.h"
#define CHECK(x) do { if(!(x))return __LINE__; } while(0)
int test_main(void){
 struct seeded_rng r;uint8_t out[65],seed[32],saved[sizeof(r)];
 const unsigned lengths[]={1,32,64,4,63,16,8,33,2,64};
 for(unsigned scenario=0;scenario<3;scenario++){
  memset(&r,0,sizeof(r));
  for(unsigned i=0;i<32;i++)seed[i]=scenario==0?0:scenario==1?i:255;
  CHECK(seeded_rng_init(&r,seed));
  for(unsigned block=0;block<10;block++){
   memset(out,0xa5,sizeof(out));CHECK(seeded_rng_read(&r,out,lengths[block]));
   CHECK(!memcmp(out,expected[scenario]+64*block,lengths[block]));
   CHECK(r.cipher.state[12]==block+1);
   for(unsigned i=lengths[block];i<sizeof(out);i++)CHECK(out[i]==0xa5);
  }
 }
 memcpy(saved,&r,sizeof(r));CHECK(seeded_rng_read(&r,0,0));CHECK(!memcmp(saved,&r,sizeof(r)));
 CHECK(!seeded_rng_init(&r,seed));CHECK(!memcmp(saved,&r,sizeof(r)));
 CHECK(!seeded_rng_read(&r,out,65));CHECK(!memcmp(saved,&r,sizeof(r)));
 CHECK(!seeded_rng_read(&r,0,1));CHECK(!memcmp(saved,&r,sizeof(r)));
 memset(&r,0,sizeof(r));for(unsigned i=0;i<32;i++)seed[i]=i;CHECK(seeded_rng_init(&r,seed));
 r.cipher.state[12]=65535;CHECK(seeded_rng_read(&r,out,32));CHECK(!memcmp(out,last_block,32));
 CHECK(r.cipher.state[12]==65536);CHECK(!seeded_rng_read(&r,out,32));
 for(unsigned i=0;i<32;i++)CHECK(out[i]==0);
 for(unsigned i=0;i<16;i++)CHECK(r.cipher.state[i]==0);
 CHECK(r.state==2);CHECK(!seeded_rng_init(&r,seed));CHECK(!seeded_rng_read(&r,out,32));
 memset(&r,0,sizeof(r));CHECK(!seeded_rng_read(&r,out,32));CHECK(r.state==2);
 memset(&r,0,sizeof(r));CHECK(seeded_rng_init(&r,seed));seeded_rng_close(&r);
 for(unsigned i=0;i<16;i++)CHECK(r.cipher.state[i]==0);
 CHECK(r.state==2);return 0;
}
